No reference labels, downloads, or input modifications.
"""
import importlib
import json
from pathlib import Path
import shutil
import subprocess

def main():
    report = {'stage': 'preflight', 'recognition_executed': False, 'dependencies': {}, 'images': [], 'baselines': []}
    for name in ['PIL', 'music21', 'converter21']:
        try:
            importlib.import_module(name)
            report['dependencies'][name] = 'available'
        except Exception as exc:
            report['dependencies'][name] = repr(exc)
    tess = shutil.which('tesseract')
    report['dependencies']['tesseract'] = tess
    if tess:
        result = subprocess.run([tess, '--version'], capture_output=True, text=True)
        report['tesseract_version'] = result.stdout.splitlines()[:1]
    if report['dependencies'].get('PIL') == 'available':
        from PIL import Image
        for path in sorted(Path('inputs').glob('sample-*.png')):
            with Image.open(path) as image:
                report['images'].append({'path': str(path), 'size': list(image.size)})
    if all(report['dependencies'].get(n) == 'available' for n in ['music21', 'converter21']):
        import converter21
        converter21.register()
        from music21 import converter
        for path in sorted(Path('baselines/audiveris-enlarged').glob('*')):
            if path.suffix not in ['.krn', '.mxl', '.musicxml']:
                continue
            item = {'path': str(path)}
            try:
                score = converter.parse(str(path))
                events = list(score.recurse().notesAndRests)
                item.update(parseable=True, note_events=sum(not e.isRest for e in events), rest_events=sum(e.isRest for e in events))
            except Exception as exc:
                item.update(parseable=False, error=repr(exc))
            report['baselines'].append(item)
    print(json.dumps(report, indent=2))

if __name__ == '__main__':
    main()
